mapper.select:
SELECT cb.post_id AS postId, cb.title, cb.category, cb.content, u.username AS username, cb.read_view AS read_view, cb.file_size AS fileSize, cb.origin_file_name AS originFileName, cb.file_name AS uuidFileName, cb.mode, cb.created_at AS createdAt, cb.updated_at AS updatedAt FROM community_board cb JOIN users u ON cb.user_id = u.id
AND ${filterType} LIKE CONCAT('%', #{query}, '%')
AND (cb.title LIKE CONCAT('%', #{query}, '%') OR cb.content LIKE CONCAT('%', #{query}, '%') OR u.username LIKE CONCAT('%', #{query}, '%') OR cb.category LIKE CONCAT('%', #{query}, '%'))
AND cb.category = #{category}
ORDER BY cb.created_at DESC LIMIT #{start}, #{pageSize}
